2117	void DispatcherNode::Vda5050StateCb(const std::string& vehicle_id,
2118	                                    const std_msgs::msg::String::SharedPtr msg) {
2119	  const auto report = amr_dispatcher_core::fleet::DeserializeVda5050State(msg->data);
2120	  if (!report.has_value()) {
2121	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
2122	                         "Malformed VDA 5050 state JSON from vehicle %s: %.128s",
2123	                         vehicle_id.c_str(), msg->data.c_str());
2124	    return;
2125	  }
2126	  // M1：状态报文必须与订阅话题的车辆身份一致，防止车 B 冒用车 A 的 orderId
2127	  // 驱动任务 A 的解锁流程。
2128	  if (report->vehicle_id != vehicle_id) {
2129	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
2130	                         "VDA 5050 state identity mismatch: topic vehicle %s but "
2131	                         "serialNumber %s — dropped",
2132	                         vehicle_id.c_str(), report->vehicle_id.c_str());
2133	    return;
2134	  }
2135	  auto link_it = vda5050_links_.find(vehicle_id);
2136	  if (link_it != vda5050_links_.end()) {
2137	    link_it->second.seen_state = true;
2138	    link_it->second.last_state_time = std::chrono::steady_clock::now();
2139	    if (!link_it->second.online) {
2140	      // 断链恢复：网关收到 state 会同步 online=true，本地视图跟随。
2141	      // 锁的解除不自动发生——Spec §5.2 要求重连后核对坐标，
2142	      // 由下方 Rule 1 的 lastNodeId 与订单一致性校验自然接管（不一致则全保留）。
2143	      link_it->second.online = true;
2144	      RCLCPP_INFO(get_logger(),
2145	                  "VDA 5050 vehicle %s reported state after offline: locks retained until "
2146	                  "lastNodeId is re-verified against the dispatched order (Spec 5.2)",
2147	                  vehicle_id.c_str());
2148	    }
2149	  }
2150	  if (report->order_id.empty() || !reservation_table_) {
2151	    return;
2152	  }
2153	  // 订单 -> 在途任务：网关订单 order_id = mission_id（BuildVda5050OrderFromPath），
2154	  // 兼容按 Mission.order_id 业务号匹配
2155	  auto mission_it = active_missions_.find(report->order_id);
2156	  if (mission_it == active_missions_.end()) {
2157	    for (auto it = active_missions_.begin(); it != active_missions_.end(); ++it) {
2158	      if (it->second.order_id == report->order_id) {
2159	        mission_it = it;
2160	        break;
2161	      }
2162	    }
2163	  }
2164	  if (mission_it == active_missions_.end()) {
2165	    return;  // 非本调度器在途任务的 state（重复/迟到/他人单）：幂等忽略，不碰锁
2166	  }
2167	  const auto path_it = mission_route_paths_.find(mission_it->first);
2168	  if (path_it == mission_route_paths_.end() || path_it->second.empty()) {
2169	    return;  // 该单无行驶路径存档（无 pickup 等）：不参与动态解锁
2170	  }
2171	  // Rule 1（Spec §5.3）：按确认位置回推身后锁，仅释放本任务持有且已整段越过的部分
2172	  std::unordered_map<std::string, std::string> held_locks;
2173	  for (const auto& [resource_id, owner] : reservation_table_->Snapshot()) {
2174	    held_locks[resource_id] = owner;
2175	  }
2176	  const auto decision = amr_dispatcher_core::workflow::PlanTrailingUnlock(
2177	      path_it->second, report->last_node_id, report->last_node_sequence_id,
2178	      mission_it->first, held_locks);
2179	  if (!decision.confirmed) {
2180	    RCLCPP_WARN(get_logger(), "Dynamic unlock skipped (vehicle %s, order %s): %s",
2181	                vehicle_id.c_str(), report->order_id.c_str(), decision.message.c_str());
2182	    return;
2183	  }
2184	  if (decision.lock_ids_to_release.empty()) {
2185	    return;  // 幂等：无新增可释放（已释放/足迹/前方锁）
2186	  }
2187	  const auto released = reservation_table_->ReleaseResources(mission_it->first,
2188	                                                             decision.lock_ids_to_release);
2189	  if (released.empty()) {
2190	    return;
2191	  }
2192	  std::string joined;
2193	  for (const auto& lock_id : released) {
2194	    if (!joined.empty()) joined += ",";
2195	    joined += lock_id;
2196	  }
2197	  RCLCPP_INFO(get_logger(),
2198	              "Dynamic unlock (Spec 5.3): vehicle %s at %s -> mission %s released %zu lock(s): %s",
2199	              vehicle_id.c_str(), report->last_node_id.c_str(), mission_it->first.c_str(),
2200	              released.size(), joined.c_str());
2201	  if (event_log_) {
2202	    amr_dispatcher_core::dispatcher::MissionEvent evt;
2203	    evt.stamp = "now";
2204	    evt.mission_id = mission_it->first;
2205	    evt.event = "dynamic_unlock";
2206	    evt.message = "vehicle " + vehicle_id + " at " + report->last_node_id + " released " + joined;
2207	    event_log_->Append(evt);
2208	  }
2209	  ReArmQueueStartRequest();  // 唤醒排队等待这批锁的后车重试派发
2210	}
