2212	void DispatcherNode::Vda5050OnlineCb(const std::string& vehicle_id,
2213	                                     const std_msgs::msg::Bool::SharedPtr msg) {
2214	  auto it = vda5050_links_.find(vehicle_id);
2215	  if (it == vda5050_links_.end()) {
2216	    return;
2217	  }
2218	  if (it->second.online == msg->data) {
2219	    return;  // 状态未变（transient_local 重放/重复报文）：不重复告警
2220	  }
2221	  it->second.online = msg->data;
2222	  if (!msg->data) {
2223	    // Rule 2（Spec §5.2 断链锁定保护）：仅标记离线 + 软看门狗告警，绝不释放任何锁。
2224	    // 锁保留直至该车重连后 state 重核对坐标，或操作员人工强制解除。
2225	    const auto guard = amr_dispatcher_core::workflow::EvaluateVehicleLinkGuard(
2226	        /*vehicle_online=*/false, /*state_stale=*/false);
2227	    RCLCPP_WARN(get_logger(), "VDA 5050 vehicle %s link broken: %s", vehicle_id.c_str(),
2228	                guard.message.c_str());
2229	    if (event_log_) {
2230	      amr_dispatcher_core::dispatcher::MissionEvent evt;
2231	      evt.stamp = "now";
2232	      evt.mission_id = "-";  // 无任务级事件：链路级看门狗告警
2233	      evt.event = "vehicle_offline";
2234	      evt.message = "vehicle " + vehicle_id + ": retaining all route locks pending "
2235	                    "reconnection and position re-verification (Spec 5.2)";
2236	      event_log_->Append(evt);
2237	    }
2238	  } else {
2239	    RCLCPP_INFO(get_logger(),
2240	                "VDA 5050 vehicle %s back online: locks retained until state re-confirms "
2241	                "lastNodeId against the order (Spec 5.2 position re-verification)",
2242	                vehicle_id.c_str());
2243	  }
2244	}
