2246	bool DispatcherNode::EnforceVda5050LinkGuard() {
2247	  if (vda5050_links_.empty()) {
2248	    return false;  // 未配置受管小车：关闭状态，零开销
2249	  }
2250	  bool blocked = false;
2251	  const auto now = std::chrono::steady_clock::now();
2252	  for (const auto& [vehicle_id, link] : vda5050_links_) {
2253	    if (!link.online) {
2254	      const auto guard = amr_dispatcher_core::workflow::EvaluateVehicleLinkGuard(
2255	          /*vehicle_online=*/false, /*state_stale=*/false);
2256	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
2257	                           "Dispatch suspended: %s (vehicle %s). On recovery the vehicle's "
2258	                           "position is re-verified via state before any lock is released.",
2259	                           guard.message.c_str(), vehicle_id.c_str());
2260	      blocked = true;  // 任一受管小车离线即挂起新派发（单车 /plan 执行模型）
2261	      continue;
2262	    }
2263	    if (link.seen_state) {
2264	      const double age_sec =
2265	          std::chrono::duration_cast<std::chrono::milliseconds>(now - link.last_state_time)
2266	              .count() /
2267	          1000.0;
2268	      if (age_sec > vda5050_state_stale_sec_) {
2269	        // 在线但 state 陈旧：仅告警——陈旧不是释放依据，也不阻塞派发（Spec §5.3）
2270	        const auto guard = amr_dispatcher_core::workflow::EvaluateVehicleLinkGuard(
2271	            /*vehicle_online=*/true, /*state_stale=*/true);
2272	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000, "VDA 5050 vehicle %s: %s",
2273	                             vehicle_id.c_str(), guard.message.c_str());
2274	      }
2275	    }
2276	  }
2277	  return blocked;
2278	}
