2280	void DispatcherNode::PublishState() {
2281	  if (!state_pub_ || !state_pub_->is_activated()) {
2282	    return;
2283	  }
2284	
2285	  amr_dispatcher_interfaces::msg::DispatcherState msg;
2286	  msg.header.stamp = now();
2287	  msg.current_comparator = queue_ ? queue_->comparator_name() : "none";
2288	  msg.queue_size = queue_ ? static_cast<uint32_t>(queue_->size()) : 0;
2289	  msg.queue_capacity = queue_ ? static_cast<uint32_t>(queue_->capacity()) : 0;
2290	  msg.active_missions_count = static_cast<uint32_t>(active_missions_.size());
2291	  msg.deadlock_detected = deadlock_flag_;
2292	
2293	  for (const auto& [id, _] : active_missions_) {
2294	    msg.active_mission_ids.push_back(id);
2295	  }
2296	  if (!msg.active_mission_ids.empty()) {
2297	    msg.active_mission_id = msg.active_mission_ids.front();
2298	  }
2299	
2300	  // ExecuteMission 进度反馈：按派发起点的直线距离折算 percent_complete
2301	  //（state_code=1 WAITING_LOCK 为计划定死的周期反馈语义；导航中的高频反馈由 NavFeedbackCb 发 state_code=2）
2302	  for (const auto& [id, handle] : execute_goal_handles_) {
2303	    if (!handle || !handle->is_executing()) {
2304	      continue;
2305	    }
2306	    auto ait = active_missions_.find(id);
2307	    if (ait == active_missions_.end()) {
2308	      continue;  // 任务已终态（finish 时会查表移除 handle）
2309	    }
2310	    double percent = 0.0;
2311	    auto sit = mission_dispatch_start_.find(id);
2312	    const bool catalog_loaded = catalog_reloader_ != nullptr && catalog_reloader_->loaded();
2313	    if (sit != mission_dispatch_start_.end() && has_odom_ && catalog_loaded &&
2314	        !ait->second.dropoff_station.empty()) {
2315	      const auto* to_st = amr_dispatcher_core::catalog::FindStation(
2316	          catalog_reloader_->catalog(), ait->second.dropoff_station);
2317	      if (to_st) {
2318	        const double total = std::hypot(to_st->x - sit->second.x, to_st->y - sit->second.y);
2319	        const double covered =
2320	            std::hypot(current_pose_.x - sit->second.x, current_pose_.y - sit->second.y);
2321	        if (total > 1e-6) {
2322	          percent = std::min(100.0, 100.0 * covered / total);
2323	        }
2324	      }
2325	    }
2326	    auto fb = std::make_shared<ExecuteMission::Feedback>();
2327	    fb->state_code = 1;  // WAITING_LOCK（计划定死的周期反馈状态）
2328	    fb->current_node = ait->second.dropoff_station;
2329	    fb->percent_complete = static_cast<float>(percent);
2330	    fb->estimated_remaining_sec = 0.0;
2331	    handle->publish_feedback(fb);
2332	  }
2333	
2334	  state_pub_->publish(msg);
2335	
2336	  // /dispatcher/topology_state：safety_gate 与 visualizer 的死锁/锁边输入
2337	  //（快照全量透传，active 仅任务持有的 route_edge，deadlocked_nodes 解析成站点 id）
2338	  if (topology_pub_ && topology_pub_->is_activated()) {
2339	    std::unordered_set<std::string> active_ids;
2340	    for (const auto& [id, _] : active_missions_) {
2341	      active_ids.insert(id);
2342	    }
2343	    const std::vector<std::pair<std::string, std::string>> snapshot =
2344	        reservation_table_ ? reservation_table_->Snapshot()
2345	                           : std::vector<std::pair<std::string, std::string>>{};
2346	    const auto topology = amr_dispatcher_core::dispatcher::BuildTopologyProjection(
2347	        snapshot, active_ids, last_deadlock_findings_);
2348	    amr_dispatcher_interfaces::msg::TopologyState topology_msg;
2349	    topology_msg.stamp = now();
2350	    topology_msg.active_edges = topology.active_edges;
2351	    topology_msg.locked_edges = topology.locked_edges;
2352	    topology_msg.edge_owners = topology.edge_owners;
2353	    topology_msg.deadlocked_nodes = topology.deadlocked_nodes;
2354	    topology_msg.deadlock_detected = topology.deadlock_detected;
2355	    topology_pub_->publish(topology_msg);
2356	  }
2357	}
