301	Vda5050GatewayNode::Vda5050GatewayNode(const rclcpp::NodeOptions& options)
302	    : rclcpp::Node("vda5050_gateway_node", options) {
303	  declare_parameter("use_vda5050", false);
304	  declare_parameter("mqtt_broker_host", "127.0.0.1");
305	  declare_parameter("mqtt_port", 1883);
306	  declare_parameter("manufacturer", "RobotManufacturer");
307	  declare_parameter("serial_number", "default");
308	  declare_parameter("protocol_version", "v2");
309	  declare_parameter("heartbeat_ms", 5000);
310	
311	  use_vda5050_ = get_parameter("use_vda5050").as_bool();
312	  mqtt_broker_host_ = get_parameter("mqtt_broker_host").as_string();
313	  mqtt_port_ = static_cast<int>(get_parameter("mqtt_port").as_int());
314	  manufacturer_ = get_parameter("manufacturer").as_string();
315	  serial_number_ = get_parameter("serial_number").as_string();
316	  protocol_version_ = get_parameter("protocol_version").as_string();
317	  heartbeat_ms_ = static_cast<int>(get_parameter("heartbeat_ms").as_int());
318	
319	  if (!use_vda5050_) {
320	    RCLCPP_INFO(get_logger(), "VDA 5050 网关未启用 (use_vda5050=false)，节点保持空转 no-op");
321	    return;
322	  }
323	
324	  if (protocol_version_ != "v2" && protocol_version_ != "v3") {
325	    RCLCPP_WARN(get_logger(), "未知 protocol_version '%s'，按 v2 处理", protocol_version_.c_str());
326	    protocol_version_ = "v2";
327	  }
328	  if (mqtt_port_ <= 0 || mqtt_port_ > 65535) {
329	    RCLCPP_WARN(get_logger(), "非法 mqtt_port=%d，回退 1883", mqtt_port_);
330	    mqtt_port_ = 1883;
331	  }
332	  if (manufacturer_.empty()) {
333	    RCLCPP_WARN(get_logger(), "manufacturer 为空，回退 RobotManufacturer");
334	    manufacturer_ = "RobotManufacturer";
335	  }
336	  if (serial_number_.empty()) {
337	    RCLCPP_WARN(get_logger(), "serial_number 为空，回退 default");
338	    serial_number_ = "default";
339	  }
340	  if (heartbeat_ms_ <= 0) {
341	    RCLCPP_WARN(get_logger(), "非法 heartbeat_ms=%d，回退 5000", heartbeat_ms_);
342	    heartbeat_ms_ = 5000;
343	  }
344	
345	  RCLCPP_INFO(get_logger(),
346	              "VDA 5050 网关启用: broker=%s:%d base=%s gateway_identity=%s/%s heartbeat=%dms",
347	              mqtt_broker_host_.c_str(), mqtt_port_, TopicBase().c_str(), manufacturer_.c_str(),
348	              serial_number_.c_str(), heartbeat_ms_);
349	
350	  try {
351	    mqtt_ = std::make_unique<MqttClientWrapper>();
352	    drain_timer_ = create_wall_timer(std::chrono::milliseconds(kDrainPeriodMs),
353	                                     std::bind(&Vda5050GatewayNode::DrainInboundQueue, this));
354	    heartbeat_timer_ = create_wall_timer(
355	        std::chrono::milliseconds(heartbeat_ms_),
356	        std::bind(&Vda5050GatewayNode::PublishGatewayHeartbeat, this));
357	    mqtt_retry_timer_ = create_wall_timer(
358	        std::chrono::milliseconds(kMqttRetryPeriodMs),
359	        std::bind(&Vda5050GatewayNode::TryConnectMqtt, this));
360	    TryConnectMqtt();
361	  } catch (const std::exception& e) {
362	    RCLCPP_ERROR(get_logger(), "MQTT 子系统初始化失败，网关降级为空转: %s", e.what());
363	    if (drain_timer_) drain_timer_->cancel();
364	    if (heartbeat_timer_) heartbeat_timer_->cancel();
365	    if (mqtt_retry_timer_) mqtt_retry_timer_->cancel();
366	    mqtt_.reset();
367	  }
368	}
369	
370	Vda5050GatewayNode::~Vda5050GatewayNode() {
371	  if (drain_timer_) drain_timer_->cancel();
372	  if (heartbeat_timer_) heartbeat_timer_->cancel();
373	  if (mqtt_retry_timer_) mqtt_retry_timer_->cancel();
374	  if (mqtt_) {
375	    // M4：优雅关机不会触发 LWT，broker 上的 retained ONLINE 若不清理会一直
376	    // 滞留（新起的调度侧会看到假在线）。先补发 retained CONNECTIONBROKEN
377	    // （QoS1 并等待 broker 确认）再断连，保证离线状态在 broker 侧收敛。
378	    // 发布失败（从未连上/已断线）静默忽略——没有可清理的 retained ONLINE。
379	    std::string err;
380	    mqtt_->Publish(MqttTopic(manufacturer_, serial_number_, "connection"),
381	                   BuildGatewayConnectionJson("CONNECTIONBROKEN"), kQosConnection,
382	                   true /*retained*/, &err, std::chrono::seconds(2));
383	    // 优雅断连：正常关机不触发 LWT 遗嘱
384	    mqtt_->Disconnect();
385	  }
386	}
