388	void Vda5050GatewayNode::TryConnectMqtt() {
389	  if (!mqtt_) return;
390	  if (mqtt_->HasConnectedOnce()) {
391	    // C1：首连成功后连接由 automatic_reconnect 接管，本定时器只剩一件事——
392	    // 重连补订阅。clean_session=true 下 broker 不保留订阅，且订阅丢失无任何
393	    // 错误信号；连接回调线程只置标志（在回调里 wait() SUBACK 会与 Paho
394	    // receiveThread 死锁），补订阅统一在执行器线程完成。
395	    if (mqtt_->ConsumeResubscribeRequest()) {
396	      std::string err;
397	      if (mqtt_->Resubscribe(&err)) {
398	        RCLCPP_INFO(get_logger(), "MQTT (重)连接后已补订阅 %s/+/+/{state,connection}",
399	                    TopicBase().c_str());
400	      } else if (err != "MQTT 未连接") {
401	        // "MQTT 未连接"属正常窗口（断线中，重连回调会再次置位），不告警
402	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
403	                             "重连后补订阅失败: %s（5s 后重试）", err.c_str());
404	      }
405	    }
406	    return;
407	  }
408	  const std::string uri = "tcp://" + mqtt_broker_host_ + ":" + std::to_string(mqtt_port_);
409	  const std::string client_id = "amr_dispatcher_gateway_" + serial_number_;
410	  // M3：按 topic 配对传 QoS（state 用 0 与发布侧对齐，connection 用 1 保证心跳到达）
411	  const std::vector<std::pair<std::string, int>> filters = {
412	      {TopicBase() + "/+/+/state", kQosState}, {TopicBase() + "/+/+/connection", kQosConnection}};
413	  // M1（观察项）：LWT payload 冻结在连接时刻的 headerId/timestamp——MQTT 3.1.1
414	  // 遗嘱在 broker 侧触发，网关无法在断线后更新它。对端若按 headerId 严格排序
415	  // 需容忍回退；payload 的 connectionState/serialNumber 不受影响。
416	  const std::string lwt_topic = MqttTopic(manufacturer_, serial_number_, "connection");
417	  const std::string lwt_payload = BuildGatewayConnectionJson("CONNECTIONBROKEN");
418	
419	  std::string err;
420	  // M7（已知取舍）：首连同步 wait 最长阻塞执行器线程 10s——v1 可接受
421	  // （仅启动期一次性成本，heartbeat/drain 在此期间暂停不影响安全）；
422	  // 失败后由本定时器每 5s 重试，首连成功即交给 automatic_reconnect。
423	  const bool ok = mqtt_->Connect(
424	      uri, client_id, filters, lwt_topic, lwt_payload, kQosConnection,
425	      [this](const std::string& topic, const std::string& payload) {
426	        OnMqttMessage(topic, payload);
427	      },
428	      &err);
429	  if (ok) {
430	    RCLCPP_INFO(get_logger(), "MQTT 已连接 %s (client_id=%s, base=%s, LWT=%s)", uri.c_str(),
431	                client_id.c_str(), TopicBase().c_str(), lwt_topic.c_str());
432	  } else {
433	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
434	                         "MQTT 连接失败 %s: %s（首连前每 5s 重试，首连成功后由自动重连接管）",
435	                         uri.c_str(), err.c_str());
436	  }
437	}
438	
439	void Vda5050GatewayNode::OnMqttMessage(const std::string& topic, std::string payload) {
440	  std::lock_guard<std::mutex> lock(inbound_mutex_);
441	  if (inbound_queue_.size() >= kMaxInboundQueue) {
442	    inbound_queue_.pop_front();
443	    dropped_messages_.fetch_add(1, std::memory_order_relaxed);
444	  }
445	  inbound_queue_.emplace_back(topic, std::move(payload));
446	}
447	
448	void Vda5050GatewayNode::DrainInboundQueue() {
449	  std::deque<std::pair<std::string, std::string>> batch;
450	  {
451	    std::lock_guard<std::mutex> lock(inbound_mutex_);
452	    batch.swap(inbound_queue_);
453	  }
454	  const std::size_t dropped = dropped_messages_.exchange(0, std::memory_order_relaxed);
455	  if (dropped > 0) {
456	    RCLCPP_WARN(get_logger(),
457	                "入站队列溢出，丢弃 %zu 条 MQTT 消息（可调低负载或提高出队频率 kDrainPeriodMs）",
458	                dropped);
459	  }
460	  for (const auto& item : batch) {
461	    const InboundTopic parsed = ParseInboundTopic(item.first);
462	    if (!parsed.valid) {
463	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "忽略无法解析的 MQTT Topic: %s",
464	                           item.first.c_str());
465	      continue;
466	    }
467	    // M2：按 (manufacturer, serialNumber) 配对过滤网关自身心跳/LWT——只比 serial
468	    // 会把同 serial 不同厂商的真车误杀，不比则其他网关的心跳会被当车辆上线
469	    if (parsed.manufacturer == manufacturer_ && parsed.vehicle_id == serial_number_) {
470	      continue;
471	    }
472	    VehicleEndpoints& ep = EnsureVehicle(parsed.vehicle_id, parsed.manufacturer);
473	    if (parsed.leaf == "state") {
474	      HandleStateMessage(parsed.vehicle_id, item.second, ep);
475	    } else {
476	      HandleConnectionMessage(parsed.vehicle_id, item.second, ep);
477	    }
478	  }
479	}
480	
481	void Vda5050GatewayNode::HandleStateMessage(const std::string& vehicle_id,
482	                                            const std::string& payload, VehicleEndpoints& ep) {
483	  if (!ep.state_pub) {
484	    return;  // 非法 vehicle_id 已在 EnsureVehicle 告警，该车无 ROS 端点
485	  }
486	  const auto report = amr_dispatcher_core::fleet::DeserializeVda5050State(payload);
487	  if (!report.has_value()) {
488	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
489	                         "丢弃非法 VDA 5050 state 报文 (vehicle=%s)", vehicle_id.c_str());
490	    return;
491	  }
492	  // 无损透传原始 JSON，Task 5 调度侧可用 DeserializeVda5050State 按需解析
493	  std_msgs::msg::String raw;
494	  raw.data = payload;
495	  ep.state_pub->publish(raw);
496	
497	  geometry_msgs::msg::PoseStamped pose;
498	  pose.header.stamp = now();
499	  pose.header.frame_id = "map";
500	  pose.pose.position.x = report->x;
501	  pose.pose.position.y = report->y;
502	  pose.pose.orientation.z = std::sin(report->yaw * 0.5);
503	  pose.pose.orientation.w = std::cos(report->yaw * 0.5);
504	  ep.pose_pub->publish(pose);
505	
506	  if (!ep.online) {
507	    ep.online = true;
508	    std_msgs::msg::Bool online_msg;
509	    online_msg.data = true;
510	    ep.online_pub->publish(online_msg);
511	  }
512	}
513	
514	void Vda5050GatewayNode::HandleConnectionMessage(const std::string& vehicle_id,
515	                                                 const std::string& payload,
516	                                                 VehicleEndpoints& ep) {
517	  const auto connection = amr_dispatcher_core::fleet::DeserializeVda5050Connection(payload);
518	  if (!connection.has_value()) {
519	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
520	                         "丢弃非法 VDA 5050 connection 报文 (vehicle=%s)", vehicle_id.c_str());
521	    return;
522	  }
523	  if (*connection == "CONNECTIONBROKEN") {
524	    // 安全铁律（Spec §3 / §5.2）：网关绝不释放任何路权锁——
525	    // 仅将 /fleet/{vid}/online 置 false；锁保留与逐段释放由调度核心 (Task 5) 负责。
526	    RCLCPP_WARN(get_logger(),
527	                "车辆 %s MQTT 连接断开 (LWT CONNECTIONBROKEN)：仅发布 /fleet/%s/online=false，"
528	                "绝不释放该车持有的路权锁（锁保留归调度核心 Task 5）",
529	                vehicle_id.c_str(), vehicle_id.c_str());
530	  }
531	  if (!ep.online_pub) {
532	    return;  // 非法 vehicle_id 无 ROS 端点
533	  }
534	  const bool online = (*connection == "ONLINE");
535	  ep.online = online;
536	  std_msgs::msg::Bool online_msg;
537	  online_msg.data = online;
538	  ep.online_pub->publish(online_msg);
539	}
