541	void Vda5050GatewayNode::SendOrderCallback(const std::string& vehicle_id,
542	                                           const std::string& manufacturer,
543	                                           const std_msgs::msg::String::SharedPtr& msg) {
544	  const std::string payload = Trim(msg->data);
545	  if (payload.empty()) {
546	    RCLCPP_WARN(get_logger(), "send_order 收到空报文 (vehicle=%s)，忽略", vehicle_id.c_str());
547	    return;
548	  }
549	  if (payload.front() != '{') {
550	    RCLCPP_WARN(get_logger(),
551	                "send_order 期望 Vda5050OrderBuilder 序列化的 Order JSON，实际开头 '%c' (vehicle=%s)，忽略",
552	                payload.front(), vehicle_id.c_str());
553	    return;
554	  }
555	  const std::string topic = MqttTopic(manufacturer, vehicle_id, "order");
556	  std::string err;
557	  if (mqtt_ && mqtt_->Publish(topic, payload, kQosOrder, false, &err)) {
558	    RCLCPP_INFO(get_logger(), "Order 已下发 MQTT: %s (%zu bytes)", topic.c_str(), payload.size());
559	  } else {
560	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "Order 下发失败 (topic=%s): %s",
561	                         topic.c_str(),
562	                         (mqtt_ == nullptr) ? "MQTT 子系统未启用" : err.c_str());
563	  }
564	}
