720	std::string Vda5050GatewayNode::BuildGatewayConnectionJson(const std::string& state) const {
721	  const std::string vda_version = (protocol_version_ == "v3") ? "3.0.0" : "2.0.0";
722	  std::ostringstream ss;
723	  ss << "{\"headerId\":" << g_connection_header_id.fetch_add(1, std::memory_order_relaxed)
724	     << ",\"timestamp\":\"" << CurrentIsoTimestampUtc() << "\","
725	     << "\"version\":\"" << vda_version << "\","
726	     << "\"manufacturer\":\"" << EscapeJsonString(manufacturer_) << "\","
727	     << "\"serialNumber\":\"" << EscapeJsonString(serial_number_) << "\","
728	     << "\"connectionState\":\"" << EscapeJsonString(state) << "\"}";
729	  return ss.str();
