#include "amr_dispatcher_ros/dispatcher_node.hpp"

#include <algorithm>
#include <chrono>
#include <cmath>
#include <unordered_set>
#include <utility>
#include <vector>

#include "amr_dispatcher_core/dispatcher/topology_projection.hpp"
