void DispatcherNode::PublishVda5050Order(const std::string& mission_id) {
  if (vda5050_vehicle_ids_.empty()) {
    return;  // 无受管 VDA 5050 小车：无订单发布（现网行为不变）
  }
  if (catalog_reloader_ == nullptr || !catalog_reloader_->loaded()) {
    RCLCPP_WARN(..., "Mission %s: catalog not loaded, VDA 5050 order not published", ...);
    return;
  }
  const auto path_it = mission_route_paths_.find(mission_id);
  if (path_it == mission_route_paths_.end() || path_it->second.empty()) {
    RCLCPP_WARN(...);  // 无路径存档：无从构建订单
    return;
  }
  if (!reservation_table_) return;
  // 本单名下持有的锁（builder 契约：严禁全局快照，防止把他人锁误判为已放行）
  std::unordered_set<std::string> held_locks;
  for (const auto& [resource_id, owner] : reservation_table_->Snapshot()) {
    if (owner == mission_id) {
      held_locks.insert(resource_id);
    }
  }
  // round-robin 绑定（保序向量游标；简单策略，见 README）
  const std::string vehicle_id = vda5050_vehicle_ids_[vda5050_rr_cursor_ % vda5050_vehicle_ids_.size()];
  vda5050_rr_cursor_ = (vda5050_rr_cursor_ + 1) % vda5050_vehicle_ids_.size();  // hmm, or just ++
  uint32_t update_id = vda5050_next_order_update_id_[vehicle_id]++;
  auto order = amr_dispatcher_core::fleet::BuildVda5050OrderFromPath(
      vehicle_id, mission_id, update_id, path_it->second, catalog_reloader_->catalog(), held_locks);
  if (!order.has_value()) {
    RCLCPP_WARN(..., "Mission %s: BuildVda5050OrderFromPath failed, no order published", ...);
    return;
  }
  const auto json = amr_dispatcher_core::fleet::SerializeVda5050Order(*order);
  auto pub_it = vda5050_order_pubs_.find(vehicle_id);
  if (pub_it == vda5050_order_pubs_.end()) {
    pub_it = vda5050_order_pubs_.emplace(
        vehicle_id,
        create_publisher<std_msgs::msg::String>("/fleet/" + vehicle_id + "/send_order", 10)).first;
  }
  std_msgs::msg::String out;
  out.data = json;
  pub_it->second->publish(out);
  RCLCPP_INFO(get_logger(),
              "VDA 5050 order published: mission %s -> vehicle %s (orderId=%s, orderUpdateId=%u, %zu nodes, %zu edges)",
              ...);
}
