  std::unordered_map<std::string, std::vector<std::string>> mission_route_paths_;
  // state 陈旧阈值（秒）：在线但超时未上报 -> 软看门狗告警（不释放、不阻塞）
  double vda5050_state_stale_sec_{5.0};

