            /*vehicle_online=*/true, /*state_stale=*/true);
        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000, "VDA 5050 vehicle %s: %s",
                             vehicle_id.c_str(), guard.message.c_str());
      }
    }
  }
  return blocked;
}

